class CustomerInsightsController:
    def __init__(self, service: OrderService, customers: CustomerService) -> None:
        self._service = service
        self._customers = customers

    def _history(self, customer_id: str) -> list[dict[str, Any]]:
        """A customer's orders, newest first, with the same totals ``handle_get`` reports.

        Raises ``CustomerNotFound`` for an unknown customer.
        """
        orders = self._service.list_for_customer(customer_id)
        history: list[dict[str, Any]] = []
        for order in reversed(orders):  # the repository returns creation order
            summary = self._service.summarize(order)
            history.append({"order_id": order.order_id, "status": order.status,
                            "total_cents": summary.total_cents})
        return history

    def _lifetime_value(self, customer_id: str) -> tuple[int, int]:
        """``(order_count, lifetime_value_cents)``: non-cancelled orders and their total.

        Raises ``CustomerNotFound`` for an unknown customer.
        """
        counted = [entry for entry in self._history(customer_id) if entry["status"] != "cancelled"]
        return len(counted), sum(entry["total_cents"] for entry in counted)

    def handle_order_history(self, customer_id: str) -> Response:
        try:
            history = self._history(customer_id)
        except CustomerNotFound:
            return not_found("customer")
        return Response(200, {"customer_id": customer_id, "orders": history})

    def handle_lifetime_value(self, customer_id: str) -> Response:
        """Number of non-cancelled orders and the sum of their totals."""
        try:
            order_count, value = self._lifetime_value(customer_id)
        except CustomerNotFound:
            return not_found("customer")
        return Response(200, {"customer_id": customer_id, "order_count": order_count,
                              "lifetime_value_cents": value})

    def handle_top_customers(self, limit: Any) -> Response:
        """Customers with the highest lifetime value, skipping those at zero."""
        try:
            limit = require_positive_int(limit, "limit")
        except InvalidRequest as exc:
            return bad_request(exc)
        ranked = []
        for customer in self._customers.list_all():
            _, value = self._lifetime_value(customer.customer_id)
            if value > 0:
                ranked.append((value, customer))
        ranked.sort(key=lambda pair: (-pair[0], pair[1].customer_id))
        return Response(200, {"customers": [
            {"customer_id": customer.customer_id, "name": customer.name, "lifetime_value_cents": value}
            for value, customer in ranked[:limit]
        ]})

